function demoMain(idx,label){
  var sessions=[["alice","bob",2],["carol","dave",3],["erin","frank",2]];
  var s=sessions[idx%sessions.length];
  return "["+label+"] session: "+s[0]+"+"+s[1]+" editing, "+s[2]+" cursors, 0 conflicts, latency 42ms";
}

